        static NumericUpDown Number(string name,decimal min,decimal max,decimal value,int decimals){return new CompactNumber{Name=name,Minimum=min,Maximum=max,DecimalPlaces=decimals,Value=value,Width=decimals>5?105:85,Increment=decimals==0?1:.5M};}
        static ComboBox Fonts(string name){var c=new ComboBox{Name=name,Width=170,DropDownStyle=ComboBoxStyle.DropDownList};c.Items.AddRange(FontFamily.Families.Select(f=>(object)f.Name).OrderBy(f=>f.ToString()).ToArray());return c;}
        static FlowLayoutPanel Flow(){return new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=true,Margin=Padding.Empty};}
        static void AddInput(FlowLayoutPanel p,string label,Control input){p.Controls.Add(new Label{Text=label,AutoSize=true,Margin=new Padding(3,5,4,0)});p.Controls.Add(input);}
        Button Tool(string icon,string text,Action action,string hint){var b=new RibbonButton(icon){Text=text};b.Click+=delegate{Guard(action);};hints.SetToolTip(b,hint);return b;}
        void Column(string property,string heading,int weight,bool read){grid.Columns.Add(new DataGridViewTextBoxColumn{Name=property,DataPropertyName=property,HeaderText=heading,FillWeight=weight,MinimumWidth=55,ReadOnly=read,SortMode=DataGridViewColumnSortMode.Programmatic});}
        void EndEdit(){if(!grid.EndEdit())throw new ArgumentException("Hoàn tất giá trị đang sửa trước.");var manager=BindingContext[items] as CurrencyManager;if(manager!=null)manager.EndCurrentEdit();}
        public LegendSpec Read(){EndEdit();spec.BlockName=blockName.Text.Trim();spec.PipeLinetypeMultiplier=(double)pipeLt.Value;spec.PipeWidthMultiplier=(double)pipeWidth.Value;spec.PipeWidthAbsolute=pipeWidthMode.SelectedIndex==1;spec.Title=title.Text;spec.TitleFont=titleFont.Text;spec.BodyFont=bodyFont.Text;spec.TitleBold=titleBold.Checked;spec.BodyBold=bodyBold.Checked;spec.Width=(double)width.Value;spec.SymbolWidth=(double)symbol.Value;spec.RowHeight=(double)rowHeight.Value;spec.TitleHeight=(double)titleHeight.Value;spec.BodyHeight=(double)bodyHeight.Value;spec.DrawingFactor=(double)factor.Value;spec.UnitMode=Math.Max(0,unitMode.SelectedIndex);spec.PrintDenominator=(double)printDenom.Value;spec.Groups=groups.SelectedIndex==0?1:2;spec.SplitAt=(int)split.Value;spec.Notes=notes.Text;spec.Rows=items.ToList();spec.Validate();return spec;}
        void LoadSpec(LegendSpec data){loading=true;try{spec=data;blockName.Text=spec.BlockName;Put(pipeLt,spec.PipeLinetypeMultiplier);Put(pipeWidth,spec.PipeWidthMultiplier);pipeWidthMode.SelectedIndex=spec.PipeWidthAbsolute?1:0;items=new BindingList<LegendRow>(spec.Rows);grid.DataSource=items;title.Text=spec.Title;SelectFont(titleFont,spec.TitleFont);SelectFont(bodyFont,spec.BodyFont);titleBold.Checked=spec.TitleBold;bodyBold.Checked=spec.BodyBold;Put(width,spec.Width);Put(symbol,spec.SymbolWidth);Put(rowHeight,spec.RowHeight);Put(titleHeight,spec.TitleHeight);Put(bodyHeight,spec.BodyHeight);Put(factor,spec.DrawingFactor);unitMode.SelectedIndex=Math.Max(0,Math.Min(3,spec.UnitMode));Put(printDenom,spec.PrintDenominator>0?spec.PrintDenominator:100);groups.SelectedIndex=spec.Groups-1;split.Value=spec.SplitAt;notes.Text=spec.Notes;}finally{loading=false;}UpdateDescriptionWidth();RefreshPreview();}
        void UpdateDescriptionWidth(){if(loading||updatingColumns||groups.SelectedIndex<0)return;double v=(double)width.Value/(groups.SelectedIndex==0?1:2)-(double)symbol.Value;if(v<15)return;updatingColumns=true;try{Put(descriptionWidth,v);}finally{updatingColumns=false;}}
        static void Put(NumericUpDown control,double value){if(!Profile.Finite(value)||value<0||value>=(double)decimal.MaxValue)throw new ArgumentException("Giá trị không nằm trong phạm vi nhập số của Windows.");decimal n=(decimal)value;if(n<control.Minimum)control.Minimum=n;if(n>control.Maximum)control.Maximum=n;control.Value=n;}
        void ApplyUnits(){if(loading||unitMode.SelectedIndex<1)return;loading=true;try{Put(factor,LegendMetrics.PaperFactor(unitMode.SelectedIndex,(double)printDenom.Value));}finally{loading=false;}RefreshPreview();}
        static void SelectFont(ComboBox c,string family){if(!c.Items.Contains(family))c.Items.Add(family);c.SelectedItem=family;}
        void AddBlankRows()
        {
            EndEdit();if(items.Count>=300)throw new ArgumentException("Bảng hỗ trợ tối đa 300 dòng.");using(var dialog=new Form{Text="Thêm hàng trống",ClientSize=new Size(340,130),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,Font=Font})
            {var input=new NumericUpDown{Minimum=1,Maximum=300-items.Count,Value=1,Left=180,Top=15,Width=120};dialog.Controls.Add(new Label{Text="Số hàng cần thêm:",Left=15,Top=19,Width=160});dialog.Controls.Add(input);var ok=new Button{Text="Thêm hàng",DialogResult=DialogResult.OK,Left=110,Top=70,Width=100};var cancel=new Button{Text="Hủy",DialogResult=DialogResult.Cancel,Left=220,Top=70,Width=80};dialog.Controls.Add(ok);dialog.Controls.Add(cancel);dialog.AcceptButton=ok;dialog.CancelButton=cancel;if(dialog.ShowDialog(this)==DialogResult.OK)for(int i=0;i<(int)input.Value;i++)items.Add(new LegendRow());}RefreshPreview();
        }
        void Add(int mode){EndEdit();var rows=capture(mode);if(rows!=null&&rows.Count>0){ClearSortIndicator();foreach(var r in rows)items.Add(r);}RefreshPreview();}
        List<int> Selected(){return grid.SelectedRows.Cast<DataGridViewRow>().Select(r=>r.Index).OrderBy(i=>i).ToList();}
        void ClearSortIndicator(){sortedProperty=null;foreach(DataGridViewColumn column in grid.Columns)column.HeaderCell.SortGlyphDirection=SortOrder.None;}
        void Repick(bool pipe)
        {
            EndEdit();var selected=Selected();if(selected.Count!=1)throw new ArgumentException("Chọn đúng một dòng để chọn lại mẫu.");int index=selected[0];var old=items[index];var captured=capture(pipe?3:2);if(captured==null||captured.Count==0)return;if(captured.Count!=1)throw new InvalidOperationException("Chọn lại cần đúng một mẫu.");var next=captured[0];next.Id=old.Id;next.Use=old.Use;next.Description=old.Description;next.SampleScale=old.SampleScale;next.PipeLinetypeFactor=old.PipeLinetypeFactor;next.PipeWidthFactor=old.PipeWidthFactor;next.Rotation=old.Rotation;next.MinHeight=old.MinHeight;next.SampleBlock=null;next.PipeBaseline=false;ClearSortIndicator();items[index]=next;grid.ClearSelection();grid.Rows[index].Selected=true;grid.CurrentCell=grid.Rows[index].Cells[3];RefreshPreview();
        }
        void SelectKind(bool pipe){EndEdit();grid.ClearSelection();DataGridViewRow first=null;foreach(DataGridViewRow row in grid.Rows){var item=row.DataBoundItem as LegendRow;if(item==null)continue;bool isPipe=item.Kind=="Nét ống";bool isShape=item.Kind=="Hình 2D"||item.Kind=="POINT"||item.Kind=="WIPEOUT";if((pipe&&isPipe)||(!pipe&&isShape)){row.Selected=true;if(first==null)first=row;}}if(first!=null){grid.CurrentCell=first.Cells[3];foreach(DataGridViewRow row in grid.Rows){var item=row.DataBoundItem as LegendRow;if(item!=null&&((pipe&&item.Kind=="Nét ống")||(!pipe&&(item.Kind=="Hình 2D"||item.Kind=="POINT"||item.Kind=="WIPEOUT"))))row.Selected=true;}}}
        void SortRows(int column)
        {
            EndEdit();if(column<0||column>=grid.Columns.Count)return;var property=grid.Columns[column].DataPropertyName;var getter=typeof(LegendRow).GetProperty(property);if(getter==null)return;ascending=sortedProperty==property?!ascending:true;sortedProperty=property;var selected=new HashSet<string>(Selected().Select(i=>items[i].Id));var current=grid.CurrentRow==null?null:((LegendRow)grid.CurrentRow.DataBoundItem).Id;var order=items.Select((item,index)=>new{item,index}).ToList();order.Sort((a,b)=>{var x=getter.GetValue(a.item,null);var y=getter.GetValue(b.item,null);int n;if(x is string||y is string)n=String.Compare(Convert.ToString(x),Convert.ToString(y),true,CultureInfo.CurrentCulture);else n=Comparer<object>.Default.Compare(x,y);if(!ascending)n=-n;return n!=0?n:a.index.CompareTo(b.index);});loading=true;try{items.RaiseListChangedEvents=false;items.Clear();foreach(var entry in order)items.Add(entry.item);items.RaiseListChangedEvents=true;items.ResetBindings();grid.ClearSelection();foreach(DataGridViewRow row in grid.Rows){var item=row.DataBoundItem as LegendRow;if(item!=null&&item.Id==current)grid.CurrentCell=row.Cells[3];}foreach(DataGridViewRow row in grid.Rows){var item=row.DataBoundItem as LegendRow;if(item!=null&&selected.Contains(item.Id))row.Selected=true;}foreach(DataGridViewColumn c in grid.Columns)c.HeaderCell.SortGlyphDirection=SortOrder.None;grid.Columns[column].HeaderCell.SortGlyphDirection=ascending?SortOrder.Ascending:SortOrder.Descending;}finally{items.RaiseListChangedEvents=true;loading=false;}RefreshPreview();
        }
        void Duplicate(){EndEdit();ClearSortIndicator();foreach(var index in Selected()){var data=new LegendSpec();data.Rows.Add(items[index]);var copy=LegendSpec.Parse(data.Serialize()).Rows[0];copy.Id=Guid.NewGuid().ToString("N");items.Add(copy);}RefreshPreview();}
        void Delete(){EndEdit();ClearSortIndicator();foreach(var i in Selected().OrderByDescending(i=>i))items.RemoveAt(i);RefreshPreview();}
        void MoveRow(int step){EndEdit();if(grid.CurrentRow==null)return;int i=grid.CurrentRow.Index,j=i+step;if(j<0||j>=items.Count)return;ClearSortIndicator();var row=items[i];items.RemoveAt(i);items.Insert(j,row);grid.ClearSelection();grid.CurrentCell=grid.Rows[j].Cells[3];grid.Rows[j].Selected=true;RefreshPreview();}
        void RefreshPreview(){if(loading||refreshing||items==null)return;refreshing=true;try{var s=Read();var l=LegendLayout.Build(s);canvas.Spec=s;canvas.PreviewLayout=l;canvas.Error=null;report.Text=(spec.LoadNote??"")+" "+l.Items.Count+" ký hiệu • "+s.Width.ToString("0.#")+" × "+l.Height.ToString("0.#")+" mm giấy (ước tính) • Hàng dài tự tăng cao. Xem bố cục; kiểm tra nét thật trong CAD/PDF.";}catch(Exception ex){canvas.Error=ex.Message;report.Text=ex.Message;}finally{refreshing=false;}canvas.Invalidate();}
        void Guard(Action action){try{action();}catch(Exception ex){report.Text=ex.Message;if(ErrorHandler!=null)ErrorHandler(ex);}}
        protected override void Dispose(bool disposing){if(disposing)hints.Dispose();base.Dispose(disposing);}
    }
    internal sealed class CompactNumber : NumericUpDown
    {
        protected override void UpdateEditText()
        {
            if(UserEdit)ValidateEditText();string format=DecimalPlaces==0?"0":"0."+new string('#',DecimalPlaces);Text=Value.ToString(format,CultureInfo.CurrentCulture);
        }
    }
    public sealed class LegendCanvas : Control
    {
        public LegendSpec Spec;public LegendLayout PreviewLayout;public string Error;public int Selected=-1;
        public LegendCanvas(){DoubleBuffered=true;BackColor=Color.FromArgb(224,230,237);}
        protected override void OnPaint(PaintEventArgs e)
        {
            base.OnPaint(e);if(Spec==null||PreviewLayout==null){TextRenderer.DrawText(e.Graphics,Error??"Thêm ký hiệu từ bản vẽ để bắt đầu.",Font,ClientRectangle,Color.DimGray,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.WordBreak);return;}
            var s=Spec;var l=PreviewLayout;float scale=(float)Math.Max(1e-8,Math.Min((Width-32)/s.Width,(Height-48)/l.Height));float x=(Width-(float)s.Width*scale)/2,y=16;var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.TranslateTransform(x,y);g.ScaleTransform(scale,scale);var page=new RectangleF(0,0,(float)s.Width,(float)l.Height);g.FillRectangle(Brushes.White,page);
            using(var pen=new Pen(Color.FromArgb(75,85,98),.18F))using(var title=MakeFont(s.TitleFont,(float)s.TitleHeight,s.TitleBold))using(var body=MakeFont(s.BodyFont,(float)s.BodyHeight,s.BodyBold))using(var format=new StringFormat{Alignment=StringAlignment.Near,LineAlignment=StringAlignment.Center})using(var centre=new StringFormat{Alignment=StringAlignment.Center,LineAlignment=StringAlignment.Center})
            {
                g.DrawRectangle(pen,0,0,page.Width,page.Height);g.DrawString(s.Title??"",title,Brushes.Black,new RectangleF(2,0,page.Width-4,(float)l.TitleHeight),centre);float top=(float)l.TitleHeight;g.DrawLine(pen,0,top,page.Width,top);
                for(int group=0;group<s.Groups;group++){float gx=(float)(group*s.Width/s.Groups),sw=(float)s.SymbolWidth,gw=(float)(s.Width/s.Groups);g.DrawString("KÝ HIỆU",body,Brushes.Black,new RectangleF(gx,top,sw,(float)l.HeaderHeight),centre);g.DrawString("DIỄN GIẢI",body,Brushes.Black,new RectangleF(gx+sw,top,gw-sw,(float)l.HeaderHeight),centre);g.DrawLine(pen,gx+sw,top,gx+sw,(float)(l.Height-l.NotesHeight));if(group>0)g.DrawLine(pen,gx,top,gx,(float)(l.Height-l.NotesHeight));}
                top+=(float)l.HeaderHeight;g.DrawLine(pen,0,top,page.Width,top);for(int r=0;r<l.DataRows;r++){float height=(float)l.Heights[r];foreach(var slot in l.Slots.Where(z=>z.Row==r)){var row=l.Items[slot.Index];float gx=(float)(slot.Column/2*s.Width/s.Groups),sw=(float)s.SymbolWidth,gw=(float)(s.Width/s.Groups);if(s.Rows.IndexOf(row)==Selected)using(var brush=new SolidBrush(Color.FromArgb(228,241,251)))g.FillRectangle(brush,gx+.2F,top+.2F,gw-.4F,height-.4F);g.DrawString(row.Description??"",body,Brushes.Black,new RectangleF(gx+sw+2,top+1,gw-sw-4,height-2),format);
                    if(row.Kind=="Nét ống"){float mid=top+height/2;g.DrawLine(pen,gx+2,mid,gx+sw-2,mid);if(!String.IsNullOrEmpty(row.Label)){var size=g.MeasureString(row.Label,body);g.FillRectangle(Brushes.White,gx+(sw-size.Width)/2-.5F,mid-size.Height/2,size.Width+1,size.Height);g.DrawString(row.Label,body,Brushes.Black,new PointF(gx+(sw-size.Width)/2,mid-size.Height/2));}}
                    else if(row.Strokes!=null&&row.Strokes.Count>0){var state=g.Save();g.TranslateTransform(gx+sw/2,top+height/2);g.RotateTransform((float)-row.Rotation);float fit=(float)(Math.Min(sw-4,height-3)*row.SampleScale);foreach(var stroke in row.Strokes){if(stroke.Points==null||stroke.Points.Length<4)continue;var points=Enumerable.Range(0,stroke.Points.Length/2).Select(i=>new PointF((float)stroke.Points[2*i]*fit,(float)-stroke.Points[2*i+1]*fit)).ToArray();if(stroke.Mask){if(points.Length>=3)g.FillPolygon(Brushes.White,points);}else g.DrawLines(pen,points);}g.Restore(state);}else if(row.Kind!="Trống")g.DrawString("["+row.Label+"]",body,Brushes.Gray,new RectangleF(gx+1,top,sw-2,height),centre);
                }top+=height;g.DrawLine(pen,0,top,page.Width,top);}
                if(l.NotesHeight>0)g.DrawString(s.Notes,body,Brushes.Black,new RectangleF(2,top+1,page.Width-4,(float)l.NotesHeight-2),format);
            }
            g.ResetTransform();TextRenderer.DrawText(g,Error??"XEM BỐ CỤC • Mẫu nét/font CAD có thể khác bản xem này",Font,new Rectangle(8,Height-28,Width-16,26),Error==null?Color.FromArgb(70,88,108):Color.Firebrick,TextFormatFlags.WordBreak|TextFormatFlags.HorizontalCenter);
        }
        static Font MakeFont(string name,float height,bool bold){return new Font(name,height, bold?FontStyle.Bold:FontStyle.Regular,GraphicsUnit.Pixel);}
    }
